<?php $typeLabel=static fn(string$type):string=>['BUY_X_GET_Y'=>'Buy X get Y','CATEGORY_BUY_N_GET_M'=>'Category buy N get M','FIXED_BUNDLE'=>'Fixed bundle'][$type]??$type;
$scopeLabel=static function(array$offer):string{if($offer['type']==='FIXED_BUNDLE'){$names=array_map(static fn($i)=>$i['product_name'].' ×'.$i['quantity'],$offer['items']??[]);return$names?implode(' + ',$names):'—';}return$offer['product_name']??$offer['category_name']??'—';};
$dealLabel=static function(array$offer):string{if($offer['type']==='FIXED_BUNDLE')return'Bundle price';return'Buy '.$offer['buy_quantity'].' get '.$offer['get_quantity'].' '.($offer['get_discount_type']==='FREE'?'free':($offer['get_discount_value'].'% off'));}; ?>
<section class="page-head"><div><p class="eyebrow">Promotions</p><h1>Bundles & offers</h1><p class="muted">These apply automatically at checkout when a cart qualifies — customers never need a code. When more items qualify than needed, the cheapest ones are always the discounted ones.</p></div><a class="button primary" href="/merchant/offers/create">Add offer</a></section>
<section class="panel offers-page-toggle"><form method="post" action="/merchant/offers-page-visibility"><?= csrf_field() ?><label class="check-row"><input type="checkbox" name="offers_page_enabled" value="1" <?= $store['offers_page_enabled']?'checked':'' ?> onchange="this.form.requestSubmit()"><span>Show a public offers page at <code>/<?= e($store['slug']) ?>/offers</code></span></label><p class="muted">Off by default. Turn this on once you have at least one active offer you want customers to browse directly.</p></form></section>
<?php if(!$offers):?><section class="empty-state panel"><div class="empty-icon">◈</div><h2>No offers yet</h2><p>Create a "buy 2 get 1 free" deal, a category-wide bundle, or a fixed combo price for specific products.</p><a class="button primary" href="/merchant/offers/create">Create first offer</a></section><?php else:?><section class="panel flush table-wrap"><table><thead><tr><th>Name</th><th>Type</th><th>Deal</th><th>Scope</th><th>Window</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($offers as$offer):?><tr><td><strong><?= e($offer['name']) ?></strong><?php if($offer['headline']):?><br><small class="muted"><?= e($offer['headline']) ?></small><?php endif ?></td><td><?= e($typeLabel($offer['type'])) ?></td><td><?= e($dealLabel($offer)) ?></td><td><?= e($scopeLabel($offer)) ?></td><td><?php if($offer['starts_at']||$offer['ends_at']):?><?= $offer['starts_at']?e(gmdate('M j',strtotime($offer['starts_at']))):'Now' ?> – <?= $offer['ends_at']?e(gmdate('M j, Y',strtotime($offer['ends_at']))):'No end' ?><?php else:?>Always on<?php endif ?></td><td><span class="badge <?= $offer['status']==='ACTIVE'?'active':'inactive' ?>"><?= e($offer['status']) ?></span></td><td class="row-actions"><a class="button compact secondary" href="/merchant/offers/<?= e($offer['id']) ?>/edit">Edit</a><form method="post" action="/merchant/offers/<?= e($offer['id']) ?>/toggle"><?= csrf_field() ?><button class="button compact ghost"><?= $offer['status']==='ACTIVE'?'Deactivate':'Activate' ?></button></form></td></tr><?php endforeach ?></tbody></table></section><?php endif ?>
